-- Freight emission factors in kg CO2e per tonne-km, generated by `shockt ref emission-factors`.
select
    factor_id,
    mode,
    variant,
    region,
    ttw_kg_co2e_per_tkm,
    wtt_kg_co2e_per_tkm,
    wtw_kg_co2e_per_tkm,
    ttw_source,
    wtt_source,
    gwp_basis,
    nullif(notes, '') as notes
from {{ ref('seed_emission_factors') }}
